package hexadecimal

import "fmt"

// ParseHex converts a hexadecimal string to its decimal equivalent.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, fmt.Errorf("syntax error: empty input")
	}
	var n int64
	for _, c := range in {
		var d int64
		switch {
		case c >= '0' && c <= '9':
			d = int64(c - '0')
		case c >= 'a' && c <= 'f':
			d = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("syntax error: invalid character %q", c)
		}
		if n > (math.MaxInt64-d)/16 {
			return 0, fmt.Errorf("range error: value out of range")
		}
		n = n*16 + d
	}
	return n, nil
}

func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		if err == nil {
			results[i] = "none"
		} else if strings.Contains(strings.ToLower(err.Error()), "range") {
			results[i] = "range"
		} else {
			results[i] = "syntax"
		}
	}
	return results
}
